fi

# D 状态进程(不可中断睡眠)
D_STATE_COUNT=$(ps aux 2>/dev/null | awk '$8~/D/{count++} END{print count+0}')
D_STATE_LIST=""
if (( D_STATE_COUNT > 0 )); then
    log_warn "发现 ${D_STATE_COUNT} 个 D 状态进程"
    D_STATE_LIST=$(ps aux 2>/dev/null | awk '$8~/D/' | head -5)
