                self._sessions[key] = conn
                return conn
            except (asyncio.TimeoutError, OSError, asyncssh.Error) as e:
                if attempt == 1:
                    raise ConnectionError(
                        f"Failed to connect to {host.hostname}: {e}"
                    ) from e
                await asyncio.sleep(2)

        raise ConnectionError(f"Unreachable: {host.hostname}")

