                    host.hostname,
                    port=host.port,
                    username=host.user,
                ),
                timeout=15,
            )
            self._sessions[f"bastion:{host.bastion}"] = bastion
            return target
        except Exception:
            bastion.close()
            raise

    async def close_all(self):
        for conn in self._sessions.values():
            try:
                conn.close()
            except Exception:
